os:store.os:value:
#[output application/json
---
{
	correlationId: correlationId,
	errorCategory: vars.errorCategory default "UNKNOWN",
	errorDescription: error.description default "No description",
	errorType: error.errorType.identifier default "UNKNOWN",
	originalPayload: write(payload, "application/json") default "{}",
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
}]

set-variable.value:
#[{
				recordId: payload.id default 'unknown',
				errorType: error.errorType.identifier,
				errorDescription: error.description,
				timestamp: now()
			}]
